CREATE OR REPLACE FUNCTION public.fijar_precio_unitario()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_precio bigint;
  v_existe boolean;
begin
  select true,
         round(p.precio * (1 - coalesce(p.descuento, 0)))::bigint
    into v_existe, v_precio
    from productos_practica p
   where p.id = new.producto_id;

  if v_existe is null then
    raise exception 'Producto % no encontrado', new.producto_id;
  end if;
  if v_precio is null then
    raise exception 'Producto % no tiene precio definido', new.producto_id;
  end if;

  new.precio_unitario := v_precio;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.validar_transicion_estado()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if new.estado = old.estado then
    return new;
  end if;

  if (old.estado, new.estado) in (
    ('carrito', 'confirmado'),  ('carrito', 'cancelado'),
    ('confirmado', 'enviado'),  ('confirmado', 'cancelado'),
    ('enviado', 'entregado'),   ('enviado', 'cancelado')
  ) then
    return new;
  end if;

  raise exception 'Transicion de estado no permitida: % -> %', old.estado, new.estado;
end;
$function$
